var n=`1020-bun-bo-hue`;var s=`world-1020`;var t=`VN`;var a=`southeast-asia`;var o=4;var r=155;var l={en:`Bun Bo Hue`,ua:`Бун бо Хюе`};var m={en:`Bun Bo Hue is a dish from Vietnam prepared with beef shank, pork hock, lemongrass, yellow onion. This is a home-scale version with measured ingredients in the individual steps where they are used. Shredded cabbage replaces banana blossom in the garnish.`,ua:`Бун бо Хюе, страва кухні країни В'єтнам, яку готують із таких продуктів: яловича гомілка, свиняча рулька, лемонграс, жовта цибуля. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Нашаткована капуста замінює банановий цвіт у гарнірі.`};var g=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 135 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 135 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:135,i:[[`beef-shank`,650,`g`],[`pork-hock`,700,`g`],[`water`,2350,`ml`],[`lemongrass`,3,`pcs`],[`yellow-onion`,170,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`annatto-seeds`,15,`g`],[`chili-oil`,45,`ml`],[`shrimp-paste`,20,`g`]]},{en:`Cook the listed ingredients in simmering water for about 8 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 8 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:8,i:[[`rice-vermicelli`,450,`g`],[`water`,1100,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`fish-sauce`,45,`ml`],[`white-cabbage`,120,`g`],[`bean-sprouts`,170,`g`],[`lime`,2,`pcs`],[`mint`,20,`g`]]}];var u={slug:n,id:s,country:`VN`,region:a,servings:4,minutes:155,title:l,text:m,steps:g};export{t as country,u as default,s as id,r as minutes,a as region,o as servings,n as slug,g as steps,m as text,l as title};